using namespace KiteWindPoll;
static void testIpv4Ranges() {
  const char* lan[] = {"10.0.0.0", "10.255.255.255", "172.16.0.0", "172.31.255.255",
                       "192.168.0.0", "192.168.255.255", "127.0.0.1", "127.255.255.255"};
  for (const char* h : lan) assert(classifyHost(h) == HostClass::LanIpv4);
  const char* pub[] = {"9.255.255.255", "11.0.0.0", "172.15.255.255", "172.32.0.0",
                       "192.167.255.255", "192.169.0.0", "126.255.255.255", "128.0.0.0",
                       "8.8.8.8", "0.0.0.0", "255.255.255.255"};
  for (const char* h : pub) assert(classifyHost(h) == HostClass::PublicIpv4);
  assert(isLanAddress(10, 1) && !isLanAddress(172, 32) && !isLanAddress(100, 64));
  assert(isLanAddress(127, 0) && !isLanAddress(8, 8) && isLanAddress(192, 168));
}
static void testMalformed() {
  const char* bad[] = {"", "010.0.0.1", "10.00.0.1", "10.0.0.01", "10.0.0", "10.0.0.0.1", "256.1.1.1",
                       "10.0.0.-1", "10..0.1", "10.0.0.1.", ".local", "a..local", "-a.local",
                       "a-.local", "a_b.local", "a b.local", "a\tb", "a\nb.local", "a\x01.local",
                       "http://10.0.0.1", "10.0.0.1:80", "host/path", "u@host", "a.b.123", "1.2.3",
                       "10.0.0.1\r\nX: y", "k\xC3\xA9.local", "localhost.", "99999999999.1.1.1"};
  for (const char* h : bad) assert(classifyHost(h) == HostClass::Invalid);
  char longLabel[80];
  for (int i = 0; i < 64; i++) longLabel[i] = 'a';
  longLabel[64] = '\0';
  assert(classifyHost(longLabel) == HostClass::Invalid);
  longLabel[63] = '\0';
  assert(classifyHost(longLabel) == HostClass::PublicName);
  assert(classifyHost(nullptr) == HostClass::Invalid);
}
static void testNames() {
  assert(classifyHost("localhost") == HostClass::Localhost);
  assert(classifyHost("LocalHost") == HostClass::Localhost);
  assert(classifyHost("kite.local") == HostClass::LocalName);
  assert(classifyHost("Kite-1.LOCAL") == HostClass::LocalName);
  assert(classifyHost("a.b.local") == HostClass::LocalName);
  assert(classifyHost("local") == HostClass::PublicName);
  assert(classifyHost("evil-local") == HostClass::PublicName);
  assert(classifyHost("evillocal") == HostClass::PublicName);
  assert(classifyHost("kite.local.evil.com") == HostClass::PublicName);
  assert(classifyHost("localhost.evil.com") == HostClass::PublicName);
  assert(classifyHost("xlocalhost") == HostClass::PublicName);
  assert(classifyHost("1.2.3.4a") == HostClass::PublicName);
  assert(classifyHost("api.kustgloed.nl") == HostClass::PublicName);
  assert(classifyHost("10.0.0.1.evil.com") == HostClass::PublicName);
}
static void testScheme() {
  // HTTPS only on port 443 and only in the S3 build.
  assert(selectScheme("api.kustgloed.nl", 443, true) == Scheme::Https);
  assert(selectScheme("api.kustgloed.nl", 443, false) == Scheme::Refused);
  assert(selectScheme("10.0.0.1", 443, true) == Scheme::Https);
  assert(selectScheme("10.0.0.1", 443, false) == Scheme::Refused);
  // Public host over HTTP is refused (status code 3).
  assert(selectScheme("api.kustgloed.nl", 8080, true) == Scheme::Refused);
  assert(selectScheme("8.8.8.8", 80, false) == Scheme::Refused);
  assert(selectScheme("evil-local", 80, false) == Scheme::Refused);
  assert(selectScheme("bad host", 80, false) == Scheme::Refused);
  assert(selectScheme("10.1.2.3", 8080, false) == Scheme::Http);
  assert(selectScheme("192.168.1.5", 80, true) == Scheme::Http);
  assert(selectScheme("localhost", 8080, false) == Scheme::Http);
  assert(selectScheme("kite.local", 8080, false) == Scheme::Http);
  assert(selectScheme("kite.local", 0, false) == Scheme::Refused);
  // Name answers must also be LAN before the key is sent.
  const uint8_t lan[4] = {192, 168, 1, 1}, pub[4] = {8, 8, 8, 8};
  const uint8_t swapped[4] = {8, 8, 8, 10}, tenNet[4] = {10, 8, 8, 8};
  assert(connectionAllowed(Scheme::Http, HostClass::LocalName, lan));
  assert(!connectionAllowed(Scheme::Http, HostClass::LocalName, pub));
  assert(!connectionAllowed(Scheme::Http, HostClass::Localhost, pub));
  assert(!connectionAllowed(Scheme::Http, HostClass::LanIpv4, pub));
  assert(!connectionAllowed(Scheme::Http, HostClass::LanIpv4, swapped));
  assert(connectionAllowed(Scheme::Http, HostClass::LanIpv4, tenNet));
  assert(!connectionAllowed(Scheme::Http, HostClass::PublicName, lan));
  assert(connectionAllowed(Scheme::Https, HostClass::PublicName, pub));
  assert(!connectionAllowed(Scheme::Https, HostClass::Invalid, lan));
  assert(!connectionAllowed(Scheme::Refused, HostClass::LanIpv4, lan));
  assert(selectScheme("0x7f000001", 80, false) == Scheme::Refused);
  assert(selectScheme("10.0.0.1", 65535, false) == Scheme::Http);
  assert(selectScheme("10.0.0.1", 65536, false) == Scheme::Refused);
}
static void testForms() {
  assert(classifyHost("0x7f000001") == HostClass::PublicName);
  const char* bad[] = {"2130706433", "0x7f.1", "[::1]", "::1", "::ffff:10.0.0.1", "fe80::1%en0"};
  for (const char* h : bad) assert(classifyHost(h) == HostClass::Invalid);
  char name[300];
  size_t n = 0;
  for (int label = 0; label < 4; label++) {
    size_t len = label < 3 ? 63 : 61;
    for (size_t i = 0; i < len; i++) name[n++] = 'a';
    if (label < 3) name[n++] = '.';
  }
  name[n] = '\0';
  assert(n == 253 && classifyHost(name) == HostClass::PublicName);
  name[n] = 'a';
  name[n + 1] = '\0';
  assert(classifyHost(name) == HostClass::Invalid);
}
static void testTimers() {
  assert(POLL_INTERVAL_MS == 600000 && HOLD_MS == 1800000);
  assert(retryDelayMs(0, false) == 600000);
  assert(retryDelayMs(1, false) == 30000 && retryDelayMs(2, false) == 60000);
  assert(retryDelayMs(3, false) == 120000 && retryDelayMs(4, false) == 300000);
  assert(retryDelayMs(5, false) == 300000 && retryDelayMs(0xFFFFFFFFu, false) == 300000);
  const unsigned samples[] = {0u, 1u, 4u, 1000u};
  for (unsigned s : samples) assert(retryDelayMs(s, true) == 600000);
  assert(nextFailures(0) == 1 && nextFailures(7) == 8);
  assert(nextFailures(FAILURE_CAP) == FAILURE_CAP);
  unsigned f = 0;
  for (int i = 0; i < 100000; i++) f = nextFailures(f);
  assert(f == FAILURE_CAP && retryDelayMs(f, false) == 300000);
  assert(holdsState(1000, 1000) && holdsState(1000, 1000 + HOLD_MS - 1));
  assert(!holdsState(1000, 1000 + HOLD_MS) && !holdsState(1000, 1000 + HOLD_MS + 1));
  assert(holdsState(0xFFFFF000u, 0x00001000u));
  assert(holdsState(0xFFFFF000u, 0xFFFFF000u + HOLD_MS - 1));
  assert(!holdsState(0xFFFFF000u, 0xFFFFF000u + HOLD_MS));
  assert(!holdsState(0xFFFFF000u, 0x00001000u + HOLD_MS));
}
int main() {
  testIpv4Ranges();
  testMalformed();
  testNames();
  testScheme();
  testForms();
  testTimers();
  std::puts("kite-wind-poll-policy-test OK");
  return 0;
}
